package ch02;

public class Hello2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		// 요구사항 - 3더하기 5의 결과화면을 출력하는 프로그램을 작성해줘
		long v1 = 3000000000L;
		long v2 = 5000000000L;
		System.out.println(v1 + v2);
		// 요구상황 - 3.2 더하기 5.4 의 결과값을 출력하는 프로그램
		double v3 = 3.2;
		double v4 = 5.4;
		System.out.println(v3 + v4);

		//
		double v5 = 3.14;
		double v6 = 5.4;
		double sum1 = (v5 + v6);
		System.out.printf("%.6f", sum1);

	}

}
